	[229] = {"229", "Лёгкое Монстро", "{{Chargeable}} Слезы заряжаются и выстреливают россыпью#↓ {{Tears}} -77% скорострельности"}, --Monstro's Lung
	[230] = {"230", "Абаддон", "↑ {{Speed}} +0.2 к скорости#↑ {{Damage}} +1.5 к урону#{{BlackHeart}} Превращает все контейнеры сердца в чёрные сердца#{{BlackHeart}} +2 чёрных сердца#{{Fear}} 15% шанс выстрелить пугающими слезами"}, -- Abaddon
	[232] = {"232", "Секундомер", "↑ {{Speed}} +0.3 к скорости#{{Slow}} Враги постоянно замедлены до 80% скорости атаки и передвижения"}, -- Stop Watch
	[233] = {"233", "Крошечная планета", "Слёзы летают по орбите вокруг вас#↑ {{Range}} +6.5 дальности#Спектральные слёзы"}, -- Tiny Planet
	[240] = {"240", "Экспериментальное лечение", "↑ Случайно увеличивает 4 характеристики #↓ Случайно уменьшает 2 характеристики"}, -- Experimental Treatment
	[245] = {"245", "20/20", "Двойной выстрел#↓ {{Damage}} x0.8 множитель урона"}, -- 20/20
	[248] = {"248", "Разум улья", "Синие пауки и мухи наносят удвоенный урон#Спутники пауки и мухи становятся сильнее"}, -- Hive Mind
	[253] = {"253", "Волшебная корка", "↑ {{Heart}} +1 к здоровью#{{Heart}} Лечит 1 красное сердце#↑ {{Luck}} +1 удача"}, -- Magic Scab
	[254] = {"254", "Сгусток крови", "!!! Применяется только к левому глазу#↑ {{Damage}} +1 урон#↑ {{Range}} +2.75 дальности"}, -- Blood Clot
	[256] = {"256", "Горячие бомбы", "{{Burning}} Горящие бомбы#Вы больше не получаете урон от огня#Бомбы наносят контактный урон#{{Bomb}} +5 бомб"}, -- Hot Bombs
	[261] = {"261", "Проптоз", "↑ {{Damage}} +0.5 к урону#↓ Слёзы наносят меньше урона, чем дольше они в воздухе#Слёзы наносят 3x урона в упор и не наносят урона через 0.8 секунды"}, -- Proptosis
	[262] = {"262", "Потерянная страница 2", "{{BlackHeart}} +1 чёрное сердце#Когда остается 1 сердце, наносит урон по комнате#Черные сердца и {{Collectible35}} эффекты Некрономикона наносят на 40 урона больше"}, -- Missing Page 2
	[263] = {"263", "Чистая руна", "{{Rune}} Копирует эффекты удерживаемой руны или камня души#Создаёт 1 случайную руну при подборе"}, -- Clear Rune   (REPENTANCE ITEM)
	[264] = {"264", "Умная муха", "Орбитальный спутник#Атакует врагов после получения урона#Наносит 6.5 контактного урона в секунду"}, -- Smart Fly
	[272] = {"272", "ББФ", "Дружелюбная взрывающаяся муха#Взрыв наносит 100 урона#{{Warning}} Взрыв может ранить персонажа"}, -- BBF
	[273] = {"273", "Мозг Боба", "Летит в направлении стрельбы и взрывается при столкновении#{{Poison}} Взрыв наносит 100 урона и отравляет врагов#{{Warning}} Взрыв может ранить персонажа"}, -- Bob's Brain
	[274] = {"274", "Лучший приятель", "При получении вами урона появляется орбитальная муха#Муха наносит 150 урона в секунду"}, -- Best Bud
	[275] = {"275", "Маленький Бримстоун", "{{Chargeable}} Спутник заряжается и стреляет {{Collectible118}} кровавым лучом#Наносит 24 урона за 0.63 секунды"}, -- Lil Brimstone
	[276] = {"276", "Сердце Исаака", "Персонаж становится неуязвимым#!!! За персонажем следует сердце. Если оно получит урон, то персонажу также будет нанесён урон#Спутник заряжается при стрельбе, после выпускает слёзы и отталкивает"}, -- Isaac's Heart
	[278] = {"278", "Тёмный бездельник", "{{Heart}} Собирает красные сердца с пола#Каждые 1.5 сердца создаёт 1 черное сердце, пилюлю, карту, руну или паука"}, -- Dark Bum
	[280] = {"280", "Сисси Длинные Ноги", "Случайно призывает синих пауков в текущей комнате#{{Charm}} Очаровывает врагов при контакте"}, -- Sissy Longlegs
	[283] = {"283", "D100", "Меняет все предметы на пьедесталах, характеристики, предметы и все артефакты#Копирует 1 случайный подбираемый предмет#Меняет текущую комнату, заменяя врагов#Заменяет камни в комнате"}, -- D100
	[285] = {"285", "D10", "Заменяет врагов в комнате#Заменяемые враги будут иметь схожее количество здоровья"}, -- D10
	[286] = {"286", "Пустая карта", "Активирует эффект удерживаемой карты, не расходуя её"}, -- Blank Card
	[287] = {"287", "Книга тайн", "При использовании показывает скрытые камни и камни с ретро сокровищницами#Даёт эффект до конца этажа: #{{Collectible54}} Карты сокровищ#{{Collectible21}} Компаса#{{Collectible246}} Синей карты#Даёт эффекты, которых у вас ещё нет#{{Collectible76}} Даёт Рентгеновское зрение, если все эффекты активны"}, -- Book of Secrets
	[288] = {"288", "Коробка с пауками", "Создает 4-8 синих пауков"}, -- Box of Spiders
	[289] = {"289", "Красная свеча", "Бросает красное пламя#Оно наносит контактный урон, блокирует вражеские слёзы и исчезает после нанесения урона или блокировки 4 выстрелов либо через 10 секунд"}, -- Red Candle
	[291] = {"291", "Слив!", "#Превращает врагов не-боссов в какашки#Сразу убивает монстров-какашек и боссов-какашек#Тушит костры и заполняет комнату водой#Превращает заполненные лавой ямы в пригодную для ходьбы землю"}, -- Flush!
	[292] = {"292", "Сатанинская Библия", "{{BlackHeart}} +1 черное сердце#{{DevilRoom}} При использовании перед боем с боссом, предмет комнаты босса станет дьявольской сделкой#Взятие этих дьявольских сделок имеет те же последствия, что и взятие сделок в дьявольских комнатах"}, -- Satanic Bible
	[293] = {"293", "Голова Крампуса", "{{Collectible118}} Выпускает кровавые лучи в 4 направлениях#Каждый луч наносит 200 урона за 1.33 секунды"}, -- Head of Krampus
	[294] = {"294", "Масленый боб", "При использовании пукает и отталкивает врагов и снаряды#Враги при попадании в объекты получают 10 урона"}, -- Butter Bean
	[295] = {"295", "Магические пальцы", "Наносит 2x урона игрока + 10 по всей комнате#{{Coin}} Стоимость: 1 монета"}, -- Magic Fingers
	[296] = {"296", "Преобразователь", "Преобразует 1 синее/черное сердце в 1 красный контейнер сердец"}, -- Converter
	--NOTE FOR LOCALIZERS: There is code to highlight the text of your current floor
	--For it to work, only use line breaks or semicolons to separate floor details, and use the same order as English
	[297] = {"297", "Ящик Пандоры", "В зависимости от этажа:#П1:2 {{SoulHeart}}#П2:2 {{Bomb}} и 2 {{Key}}#К1:1 артефакт {{BossRoom}}#K2:П1+К1#Г1:4 {{SoulHeart}}#Г2: 20 {{Coin}}#У1:2 артефакта {{BossRoom}}#У2: {{Collectible33}} Библия#???/Пустота: Ничего#Шеол: 1 артефакт {{DevilRoom}} + 1 {{BlackHeart}}#Собор: 1 артефакт {{AngelRoom}} + 1 {{EternalHeart}}#Тёмная комната: {{Collectible523}} Открывает Коробку для перевозки#Сундук: 1 {{Coin}}#Дом: {{Collectible580}} Красный ключ"}, -- Pandora's box
	[300] = {"300", "Овен", "↑ {{Speed}} +0.25 скорости#При скорости выше 0.85 персонаж не получает контактный урон и наносит врагам 25 урона"}, -- Aries
	[307] = {"307", "Козерог", "↑ {{Heart}} +1 к здоровью#↑ {{Damage}} +0.5 урона#↑ {{Speed}} +0.1 скорости#↑ {{Range}} +0.75 дальности#↑ {{Tears}} +0.5 скорострельности#+1 ключ, бомба, монета"}, -- Capricorn
	[308] = {"308", "Водолей", "Персонаж оставляет за собой след жижи#{{Damage}} Жижа наносит 666% урона персонажа в секунду и наследует эффекты его слёз"}, -- Aquarius
	[309] =	{"309", "Рыбы", "↑ {{Tears}} +0.5 к скорострельности#↑ {{Tearsize}} +0.12 к размеру слезы#Увеличивает отбрасывание от слёз"}, -- Pisces
	[310] = {"310", "Тушь Евы", "↑ {{Damage}} +100% урона#↓ {{Tears}} -33% скорострельности#↓ {{Shotspeed}} -0.5 скорости слезы"}, -- Eve's Mascara
	[311] = {"311", "Тень Иуды", "{{Player12}} После смерти вы появитесь в виде Тёмного Иуды#(он имеет урон x2 и + к скорости)#{{Player24}} Порченый Иуда возродится собой"}, -- Judas' Shadow
	[312] = {"312", "Лук Магдалины", "↑ {{Heart}} +1 к здоровью#{{HealingRed}} Лечит 1 красное сердце#Все красные сердца лечат вдвое больше"}, -- Maggy's Bow
	[314] = {"314", "Громовые бёдра", "↑ {{Heart}} +1 к здоровью# {{Heart}} Лечит 1 красное сердце#↓ {{Speed}} -0.4 скорости#Вы можете ломать камни, растаптывая их"}, -- Thunder Thighs
	[315] = {"315", "Странное влечение", "Магнитные слезы#Притягивают предметы и врагов#Предметы притягиваются к месту падения слезы"}, -- Strange Attractor
	[316] = {"316", "Проклятый глаз", "{{Chargeable}} Заряжаемая очередь из 5 слёз#{{Warning}} Получение урона при неполном заряде телепортирует персонажа в случайную комнату"}, -- Cursed Eye
	[319] = {"319", "Другой глаз Каина", "Стреляет слезами в случайное направление, копируя эффекты слез Айзека#{{Damage}} Наносит 75% вашего урона"}, -- Cain's Other Eye
	[320] = {"320", "Единственный друг ???", "Управляемая муха#Наносит 15 контактного урона в секунду"}, -- ???'s Only Friend
	[322] = {"322", "Малыш Монго", "Повторяет слёзы других спутников#Если спутников нет, стреляет обычными слезами с уроном 3.5"}, -- Mongo Baby
	[323] = {"323", "Слёзы Исаака", "Выпускает 8 слёз во все стороны#Слёзы копируют эффекты персонажа и получают +5 урона#Перезаряжается при стрельбе"}, -- Isaac's Tears
	[325] = {"325", "Ножницы", "{{Timer}} До конца комнаты голова становится неподвижным стреляющим спутником#Тело управляется отдельно и выпускает кровавые слёзы в направлении стрельбы"}, -- Scissors
	[326] = {"326", "Дыхание жизни", "Удержание кнопки USE опустошает полосу заряда#Персонаж временно неуязвим, когда полоса заряда пуста#При контакте с врагами во время неуязвимости призывает лучи света#При блокировании урона с идеальной точностью выстреливает 4-сторонним святым лучом и даёт кратковременный щит#{{Warning}} Слишком долгое удержание наносит урон персонажу"}, -- Breath of Life
	[327] = {"327", "Фотокарточка", "Дает короткую неуязвимость, если осталось 1/2 или нет красных сердец#Позволяет пройти на этаж Сундук#Позволяет открыть Странную дверь"}, -- The Negative
	[328] = {"328", "Негатив", "↑ {{Damage}} +1 урон#Наносит урон всем врагам в комнате, если осталось 1/2 или нет красных сердец#Позволяет пройти на этаж Темная комната#Позволяет открыть Странную дверь"}, -- The Negative
	[330] = {"330", "Соевое молоко", "↑ {{Tears}} +450% скорострельности#↓ {{Damage}} -80% урона#Сильно уменьшается отталкивание"}, -- Soy Milk
	[331] = {"331", "Божественность", "↑ {{Damage}} +0.5 урона#↓ {{Tears}} -0.3 скорострельности#↓ {{Shotspeed}} -0.3 скорости слезы#Слёзы получают ауру, наносящую 60 урона в секунду#Самонаводящиеся слезы"}, -- Godhead
	[332] = {"332", "Лохмотья Лазаря", "{{Player11}} После смерти вы появитесь в виде Лазаря и получите его артефакт#{{Player29}} Порченый Лазарь возродится собой"}, -- Lazarus' Rags
	[336] = {"336", "Мертвый лук", "Сквозные и спектральные слезы#↓ {{Range}} -1.5 дальности#↓ {{Shotspeed}} -0.4 скорости слезы#↑ {{Tearsize}} +0.22 к размеру слезы"}, -- Dead Onion
	[339] = {"339", "Безопасная булавка", "↑ {{Range}} +2.5 дальности#↑ {{Shotspeed}} +0.16 скорости слезы#{{BlackHeart}} +1 чёрное сердце"}, -- Safety Pin
	[342] = {"342", "Голубая шляпка", "↑ {{Heart}} +1 к здоровью#{{HealingRed}} Лечит 1 красное сердце#↑ {{Tears}} +0.7 скорострельности#↓ {{Shotspeed}} -0.16 скорости слезы"}, -- Blue Cap
	[344] = {"344", "Коробок спичек", "{{BlackHeart}} +1 чёрное сердце#{{Bomb}} Создает 3 бомбы#{{Trinket41}} Создает брелок Спичку"}, -- Match Book
	[345] = {"345", "Синтол", "↑ {{Damage}} +1 урон#↑ {{Range}} +2.5 дальности"}, -- Synthoil
	[346] = {"346", "Закуска", "↑ {{Heart}} +1 к здоровью#{{Heart}} Лечит 1 красное сердце"}, -- A Snack
	[349] = {"349", "Деревянный пятак", "{{Coin}} 59% шанс создать случайную монету"}, -- Wooden Nickel
	[350] = {"350", "Токсический шок", "{{Poison}} При заходе в комнату все враги получают отравление#Даёт иммунитет к токсичным облакам#Убитые враги оставляют зелёную лужу"}, -- Toxic Shock
	[352] = {"352", "Стеклянная пушка", "{{Damage}} Выстреливает большой пронзающей призрачной слезой, которая наносит 10x урона персонажа +10 урона#{{Warning}} Пока удерживается, при получении урона:#↓ Отнимает дополнительно 2 сердца здоровья#↓ Ломает пушку на несколько комнат#↑ {{Range}} +1.5 к дальности и оставляет кровавый след до конца комнаты#Дополнительный урон не может убить персонажа#Самоповреждение не активирует эффект"}, -- Glass Canon
	[353] = {"353", "Мальчик-бомбардировщик", "{{Bomb}} +5 бомб#Бомбы взрываются крестом#↓ x0.75 урона бомб"}, -- Bomber Boy
	[354] = {"354", "Хрустящий Джек", "↑ {{Heart}} +1 к здоровью#{{Heart}} Лечит 1 красное сердце#{{Trinket}} Создает случайный брелок на полу"}, -- Crack Jacks
	[355] = {"355", "Мамин жемчуг", "↑ {{Range}} +2.5 дальности#↑ {{Luck}} +1 удача#{{SoulHeart}} +1 синее сердце"}, -- Mom's Pearls
	[360] = {"360", "Инкуб", "Стреляет слезами с эффектами персонажа#{{Damage}} Наносит 75% его урона (100% за Лилит и Порченую Лилит)"}, -- Incubus
	[365] = {"365", "Потерянная муха", "Летит вдоль стен и препятствий в комнате#Наносит 30 контактного урона в секунду#Ближайшие враги будут следовать за мухой"},
	[366] = {"366", "Разбросанные бомбы", "{{Bomb}} +5 бомб#Бомба разделяется на 4-5 маленьких бомб после взрыва"}, -- Scatter Bombs
	[367] = {"367", "Липкие бомбы", "{{Bomb}} +5 бомб#{{Slow}} Бомбы прилипают к врагам и оставляют замедляющую белую лужу#Убийство врага бомбой создаёт синих пауков"}, -- Sticky Bombs
	[368] =	{"368", "Эпифора", "↑ {{Tears}} Стрельба в одном направлении постепенно увеличивает скорострельность до 200%"}, -- Epiphora
	[369] = {"369", "Континуум", "↑ {{Range}} +3 дальности#Спектральные слёзы#Слезы проходят сквозь стены и появляются из противоположной стены"}, -- Continuum
	[370] = {"370", "Мистер Куколка", "↑ {{Tears}} +0.7 скорострельности#↑ {{Range}} +2.5 дальности#{{UnknownHeart}} Создает 3 случайных сердца"}, -- Mr. Dolly
	--[372] = {"372", "Заряженный малыш", "Со случайным шансом создает микро батарейку или на время заморозит всех врагов#Шанс получить 1 заряд активируемого предмета"}, -- Charged Baby
	[374] = {"374", "Божественный свет", "10% шанс выстрелить Святой Слезой, выпускающей Луч Света при попадании по врагу#{{Damage}} Луч наносит 3x вашего урона#{{Luck}} 50% шанс при 9 удачи"}, -- Holy Light
	[375] = {"375", "Шляпа Наблюдателя", "Иммунитет от взрывов#20% шанс отразить снаряд#Блокирует снаряды, падающие сверху"}, -- Host hat
	[376] = {"376", "Пополнение", "Обновляет предметы в магазине после покупки#После пополнения увеличивается цена"}, -- Restock
	[380] = {"380", "Плати и играй", "{{Coin}} +5 монет#Вы теперь открываете закрытые двери и сундуки монетами, вместо ключей"}, -- Pay To Play
	[382] = {"382", "Дружелюбный шар", "Можно бросить во врага, чтобы поймать его#После следующего броска пойманное существо появится как союзное#Ходьба по шару после захвата мгновенно перезарядит его"}, -- Friendly Ball
	[384] = {"384", "Малютка Гёрди", "{{Chargeable}} Заряжается и атакует врагов с разгона#Наносит 5-20 контактного урона при попадании в зависимости от скорости"}, -- Lil Gurdy
	[386] = {"386", "D12", "Изменяет все препятствия в комнате на случайные препятствия#С небольшим шансом может создать кнопки, выключатели, ретро-сокровищницы или люки"}, -- D12
	[389] = {"389", "Мешочек с рунами", "{{Rune}} Создает случайную руну или камень души каждые 7-8 комнат"}, -- Rune Bag
	[391] = {"391", "Предательство", "Враги могут попасть своими слезами друг по другу, после чего они начнут сражаться между собой"}, -- Betrayal
	[393] = {"393", "Змеиный поцелуй", "{{Poison}} 15% шанс выстрелить отравляющей слезой#{{Luck}} Не зависит от удачи#{{Poison}} Отравляет врагов при касании#{{BlackHeart}} Отравленные касанием враги после смерти с шансом 20% оставляют черное сердце"}, -- Serpent`s Kiss
	[394] = {"394", "Отмеченный", "Вы стреляете слезами в направлении маркера, которым вы управляете#↑ {{Tears}} +0.7 скорострельности#↑ {{Range}} +3 дальности#Спутники стреляют по направлению маркера"}, -- Marked
	[395] = {"395", "Технология X", "{{Chargeable}} Вы атакуете заряжающимися лазерными кольцами#Урон зависит от длительности зарядки#100% при полной зарядке"}, -- Tech X
	[397] = {"397", "Тяговый луч", "Ваши слезы летят строго вдоль луча света, не отклоняясь даже при вашем движении#↑ {{Tears}} +1 скорострельность#↑ {{Range}} +2.5 дальности#↑ {{Shotspeed}} +0.16 к скорости слезы"},
	[399] = {"399", "Пасть бездны", "{{Chargeable}} После непрерывной стрельбы в течение 2.35 секунды отпускание кнопки стрельбы создаёт вокруг персонажа чёрное кольцо#{{Damage}} Кольцо наносит 30x урона персонажа за 2 секунды"}, -- Maw of the Void
	[401] = {"401", "Взрывчатко", "25% шанс выстрелить липкой слезой#Через несколько секунд она взрывается, нанося урон персонажа +60"}, -- Explosivo
	[404] = {"404", "Пукающий малыш", "Блокирует снаряды#При попадании имеет 10% шанс пукнуть и {{Charm}} очаровать, {{Poison}} отравить или отбросить врагов#Пуки наносят 5-6 урона"}, -- Farting Baby
	[405] = {"405", "Игровой баг", "{{Throwable}} {{ColorOrange}}Бросаемое{{CR}} #Заменяет врагов и предметы на полу при контакте с ними"}, -- GB Bug
	[407] = {"407", "Чистота", "Даёт ауру со случайным бонусом; урон снимает её до следующей комнаты#{{ColorRed}}Красная{{CR}}: ↑ {{Damage}} +4 урона#{{ColorBlue}}Синяя{{CR}}: ↑ {{Tears}} +2 скорострельности#{{ColorYellow}}Жёлтая{{CR}}: ↑ {{Speed}} +0.5 скорости#{{ColorOrange}}Оранжевая{{CR}}: ↑ {{Range}} +3 дальности"},
	[408] = {"408", "Атаме", "25% шанс создать чёрное кольцо Бримстоуна вокруг убитых врагов#Оно наносит 30x урона персонажа за 2 секунды#{{Luck}} +2.5% шанса за каждую единицу удачи"}, -- Athame
	--[409] = {"409", "Пустой сосуд", "+2 Черных Сердца#Если у персонажа нет красных сердец:#Дает полет#10 секунд неуязвимости в комнате с врагами, когда секунды на таймере достигли 00, 20 или 40 хотя бы дважды"},
	[415] = {"415", "Корона света", "{{SoulHeart}} +2 синих сердца#Если нет неполных красных сердец:#↑ {{Damage}} x2 множитель урона#↓ {{Shotspeed}} -0.3 скорости слезы#При получении урона бонус сбрасывается до конца комнаты"},
	[416] = {"416", "Глубокие карманы", "Создает 1-3 случайных монет, если после зачистки комнаты вы не получили награду#Увеличивает максимальное количество монет до 999"}, -- Deep Pockets
	[417] = {"417", "Суккуб", "Летает по комнате, имеет ауру, которая наносит врагам 7.5-10 урона в секунду#↑ {{Damage}} +50% к урону при нахождении внутри ауры"}, -- Succubus
	[419] = {"419", "Телепорт 2.0", "Телепортирует в случайную комнату, которая ещё не зачищена#Иерархия: {{Room}}>{{BossRoom}}>{{SuperSecretRoom}}>{{Shop}}>{{TreasureRoom}}>{{SacrificeRoom}}> {{DiceRoom}}>{{Library}}>{{CursedRoom}}>{{MiniBoss}}>{{ChallengeRoom}}>{{IsaacsRoom}}> {{ArcadeRoom}}>{{ChestRoom}}>{{Planetarium}}>{{SecretRoom}}>{{DevilRoom}}{{AngelRoom}}> Комната-ошибка"}, -- Teleport 2.0
	[421] = {"421", "Почечный боб", "Накладывает очарование на ближайших врагов при активации"}, -- Kidney Bean
	[422] = {"422", "Светящиеся песочные часы", "Возвращает персонажа в предыдущую комнату и отменяет действия, совершённые в комнате использования#Можно перемотать время 3 раза за этаж#{{Collectible66}} После исчерпания перемоток действует как Песочные часы и замедляет врагов на 8 секунд"}, -- Glowing Hourglass
	[426] = {"426", "Одержимый фанат", "Повторяет движения с задержкой в 0.66 секунды#Наносит 30 контактного урона в секунду"}, -- Obsessed Fan
	[430] = {"430", "Папа-мух", "Повторяет движения с задержкой в 0.66 секунды#Стреляет в ближайших врагов нанося урон, равный урону персонажа"}, -- Papa Fly
	[431] = {"431", "Многомерный малыш", "Повторяет движения персонажа с задержкой 0.66 секунды#Слёзы, проходящие через него, удваиваются и получают бонус к дальности и скорости полёта"}, -- "Multidimensional Baby
	[432] = {"432", "Блестящие бомбы", "{{Bomb}} +5 бомб#{{Charm}} Взрыв бомбы с шансом 63% создаёт случайный подбираемый предмет и с шансом 15% очаровывает врагов#Шанс создания снижается на 1% за каждое срабатывание на этаже"}, -- Glitter Bombs
	[433] = {"433", "Моя тень", "За персонажем следует маленькая тень#{{Friendly}} При касании врага тени до конца комнаты появляется дружелюбный чёрный червь#Он наносит 8.7 урона за удар"}, -- My Shadow
	[437] = {"437", "D7", "Восстанавливает ранее убитых врагов в комнате#Позволяет повторно получить награду за зачистку комнаты"}, -- D7
	[440] = {"440", "Почечный камень", "В случайный момент персонаж перестанет стрелять, чтобы зарядить залповую атаку#Персонаж выплюнет почечный камень, наносящий большой урон, а затем выпустит шквал слез с очень высокой скоростью"}, -- Kidney Stone
	[442] = {"442", "Корона тёмного принца", "!!! Если есть ровно 1 красное сердце:#↑ {{Range}} +1.5 к дальности#↑ {{Tears}} +2.0 к скорострельности#↑ {{Shotspeed}} +0.2 к скорости слезы#(Не работает с персонажами, у которых нет красного здоровья, кроме Хранителя)"}, -- Dark Princes Crown
	[444] = {"444", "Графитовый карандаш", "Каждый 15 выстрел вы будете выпускать большую россыпь слез"}, -- Lead Pencil
	[448] = {"448", "Осколок стекла", "При получении урона:#{{Heart}} 25% шанс создать красное сердце#{{BleedingOut}} Персонаж истекает кровью, извергая слёзы в направлении стрельбы#Кровотечение наносит половину красного сердца урона каждые 20 секунд#Кровотечение прекращается, если исцеляется красное сердце, все красные сердца пусты или следующий урон убьёт персонажа"}, -- Shard of Glass
	[450] = {"450", "Глаз Алчности", "Каждые 20 выстрелов, выстреливает слезу-монетку, наносящую х1.5 урона + 10#Задетый враг бросит монетку и временно превратится в золото#Золотой враг оставит 1-3 монетки при убийстве#!!! Слеза-монетка стоит 1 монетку"}, -- Eye of Greed
	[451] = {"451", "Сукно Таро", "Дает случайную карту или руну#Усиливает эффект некоторых используемых карт"}, -- Tarot Cloth
	[453] = {"453", "Перелом", "↑ {{Range}} +1.5 дальности#Костяные слёзы#При столкновении разделяются на 1-3 осколка"}, -- Compound Fracture
	[455] = {"455", "Папина потерянная монета", "↑ {{Range}} +2.5 дальности#{{Luck}} Создаёт счастливую монетку"},
	[456] = {"456", "Полуночный перекус", "↑ {{Heart}} +1 к здоровью#Лечит 1 красное сердце"}, -- Midnight Snack
	[459] = {"459", "Синусит", "20% шанс выстрелить липкой соплёй#{{Damage}} Сопли наносят урон персонажа раз в секунду и прилипают на 10 секунд#{{Luck}} Не зависит от удачи"}, -- Sinus Infection
	[462] = {"462", "Глаз Белиала", "↑ {{Range}} +1.5 дальности#Даёт пронзающие слёзы#После попадания по первому врагу, слеза нанесёт двойной урон и получит эффект самонаведения"}, -- Eye of Belial
	[464] = {"464", "Символ баланса", "+2 синих сердца#С монстров-чемпионов и при зачистке комнат чаще выпадают предметы#Приоритет на выпадение предметов, которых не хватает игроку"}, -- Glyph of Balance
	[468] = {"468", "Тень", "Повторяет движения персонажа с задержкой 0.66 секунды#Наносит 75 контактного урона в секунду#{{Friendly}} После нанесения 666 урона поглощается персонажем, увеличивая его контактный урон и создавая дружелюбных червей"}, -- Shade
	[472] = {"472", "Малыш король", "Все спутники следуют за ним и автоматически стреляют во врагов#Останавливается во время стрельбы#Телепортируется обратно к вам, когда вы перестаете стрелять"}, -- King Baby
	[474] = {"474", "Разбитая стеклянная пушка", "При использовании превращается в стеклянную пушку"}, -- broken Glass Canon
	[476] = {"476", "D1", "Дублирует 1 случайный подбираемый предмет в комнате#Дублированный предмет может быть вариантом этого предмета, а не точной копией"}, -- D1
	[477] = {"477", "Пустота", "!!! При использовании поглощает все артефакты на пьедесталах в комнате#Активируемый артефакт: его эффект будет активироваться при каждом следующем использовании Пустоты#↑ Пассивный артефакт: небольшие увеличения двух случайных характеристик"},
	[487] = {"487", "Картофелечистка", "{{EmptyHeart}} Убирает 1 контейнер здоровья и даёт:#↑ {{Damage}} +0.2 урона#{{Collectible73}} Кубик мяса#{{Timer}} До конца комнаты:#↑ {{Range}} +1.5 дальности#{{Collectible214}} Кровавый след"}, -- Potato Peeler
	[489] = {"489", "D Бесконечность", "Может действовать как любой предмет-кубик (кроме {{Collectible723}} Кубика отката) с помощью кнопки выброса ({{ButtonRT}})#Время заряда зависит от последнего использованного кубика и обновляется при каждом использовании"}, -- D Infinity
	[491] = {"491", "Кислотный малыш", "Дает случайную пилюлю каждые 7 комнат#Каждое использование пилюли отравляет врагов в комнате"}, -- Acid Baby
	[493] = {"493", "Адреналин", "За каждый пустой контейнер красных сердец:#↑ {{Damage}} Увеличивает урон по формуле: ((2 * Отсутствующие половины сердец) ^ 1.6) * 0.1"}, -- Adrenaline
	[494] = {"494", "Лестница Иакова", "Слёзы создают искру электричества при попадании#Искры наносят половину урона персонажа#Искры могут перескакивать на 4 других врагов"}, -- Jacob's Ladder
	[495] = {"495", "Призрачный перец", "8% шанс выстрелить синим огнём, который блокирует снаряды врагов и наносит контактный урон#{{Luck}} 50% шанс при 10 удачи#Огонь исчезает после 2 секунд"}, -- Ghost Pepper
	[496] = {"496", "Эвтаназия", "3.33% шанс выстрелить иглой#{{Luck}} 25% шанс при 13 удачи#Иглы мгновенно убивают обычных врагов, разрывая их на 10 слёз#{{Damage}} Иглы наносят 3x урона против боссов"}, -- Euthanasia
	[497] = {"497", "Камуфляжные трусы", "Сбивает с толку всех врагов и камуфлирует персонажа при заходе в комнату до тех пор, пока вы не начнете стрелять#↑ {{Speed}} +0.5 скорости при комуфляже#При сбросе комуфляжа, наносит урон вокруг персонажа и даёт очень короткое увеличение скорострельности и урона"}, -- Camo Undies
	[498] = {"498", "Двойственность", "{{AngelDevilChance}} При появлении сделки после босса создаёт Комнаты Дьявола И Ангела одновременно#При заходе в одну, другая исчезнет"}, -- Duality
	[500] = {"500", "Мешок мешков", "Создает мешок каждые 7-8 комнат"}, -- Sack of Sacks
	[501] = {"501", "Глотка Жадности", "↑ {{Heart}} +1 контейнер сердца за каждые 25 монет"}, -- Greed's Gullet
	[503] = {"503", "Маленький рог", "5% шанс выстрелить слезой, призывающей руку Большого Рога#{{Luck}} 20% шанс при 15 удачи#Рука мгновенно убивает обычных врагов и наносит боссам 36 урона#Персонаж наносит 7 контактного урона в секунду"}, -- Little Horn
	[504] = {"504", "Коричневый самородок", "При использовании призывает союзную муху-турель, атакующую врагов#Каждый выстрел наносит по 3.5 урона"}, -- Brown Nugget
	[506] = {"506", "Предатель", "При попадании по врагу со спины наносится двойной урон и накладывается кровотечение, которое заставляет врагов оставлять кровавый след и получать урон при движении"}, -- Backstabber
	[507] = {"507", "Острая соломинка", "{{Damage}} Наносит ваш урон + 10% от макс. здоровья врага#Действует на всех врагов в комнате#{{HalfHeart}} 15% шанс создать половину красного сердца при нанесении урона"}, -- Sharp Straw
	[508] = {"508", "Мамина бритва", "Орбитальный спутник, при контакте накладывает кровотечение, которое заставляет врагов получать урон при движении#{{Damage}} Наносит 1.5x урона персонажа в секунду"}, -- Mom's Razor
	[509] = {"509", "Кровоточащий глаз", "Орбитальный спутник, который стреляет слезой каждые 0.33 секунды по ближайшим врагам#Наносит 3.5 урона за слезу#Наносит 20 контактного урона в секунду"}, -- Bloodshot Eye
	[514] = {"514", "Сломанный модем", "Вызывает 'лаги' у врагов и их снарядов случайным образом#Снаряды при этом через некоторое время исчезнут#С шансом 25% подбираемые предметы могут залагать и удвоиться"},
	[517] = {"517", "Быстрые бомбы", "+7 бомб#Позволяет быстро ставить бомбы на пол#Бомбы не отталкивают друг друга"}, -- Fast Bombs
	[522] = {"522", "Телекинез", "На 3 секунды останавливает все приближающиеся вражеские снаряды, после чего отбрасывает их#Во время эффекта отталкивает ближайших врагов"}, -- Telekinesis
	[523] = {"523", "Коробка для перевозки", "При использовании подбирает до 10 предметов и артефактов в комнате#Повторное использование создает эти предметы на полу#Позволяет перемещать предметы между комнатами"}, -- Moving Box
	[524] = {"524", "Технология Ноль", "Слёзы персонажа соединены электрическими лучами#Электричество наносит 4.5x урона персонажа в секунду"}, -- Technology Zero
	[525] = {"525", "Проказа", "При получении урона создаёт орбитального спутника, блокирующего снаряды#Максимум 3 спутника#Они наносят 30 контактного урона в секунду и разрушаются после нескольких попаданий"}, -- Leprosy
	[531] = {"531", "Гемолакрия", "↑ {{Damage}} +1 урона#↑ {{Damage}} x1.5 множитель урона#↓ {{Tears}} x0.33 множитель скорострельности#↓ {{Range}} x0.8 множитель дальности#Слёзы летят по дуге и при столкновении разлетаются на маленькие слёзы"}, -- Haemolacria
	[532] = {"532", "Слезопоглощение", "Слёзы постепенно замедляются, останавливаются и разлетаются на 5-8 маленьких слёз#Слёзы могут сливаться и увеличиваться"}, -- Lachryphagy
	[535] = {"535", "Одеяло", "{{SoulHeart}} +1 синее сердце#{{Heart}} Лечит 1 красное сердце#{{HolyMantle}} Дает одноразовый щит в комнате с Боссом"},
	[543] = {"543", "Освящённая земля", "Получение урона создаёт белую какашку#Находясь в её ауре:#↑ {{Tears}} x2.5 множитель скорострельности#↑ {{Damage}} x1.2 множитель урона#Самонаводящиеся слёзы#50% шанс блокировать урон"}, -- Hallowed Ground
	[549] =	{"549", "Хрупкие кости", "Заменяет все ваши красные сердца 6 Костяными Сердцами#При потере Костяного Сердца:#Выстреливает 8 слёз-костей во все стороны#↑ {{Tears}} +0.4 постоянной скорострельности"}, -- Brittle Bones
	[552] = {"552", "Мамина лопата", "При использовании создает на полу люк на следующий этаж#{{LadderRoom}} Создаёт Ретро сокровищницу, если использовано на клетке пола с декорацией (трава, маленькие камешки, бумажки, и т.д.)"}, --Mom's Shovel
	[553] = {"553", "Мукормикос", "25% шанс выстрелить липкой споровой слезой#{{Luck}} Не зависит от удачи#{{Poison}} Споры взрываются через 2.5 секунды, нанося урон, отравляя ближайших врагов и выпуская больше спор"}, --  Mucormycosis
	[554] = {"554", "Очжутко", "Накладывает страх на врагов в небольшом радиусе вокруг персонажа"}, --  2Spooky
	[555] = {"555", "Золотая бритва", "+5 монет#Забирает 5 монет и даёт 1.2 к урону на текущую комнату"}, --  Golden Razor
	[556] = {"556", "Сульфур", "Дает {{Collectible118}} кровавый лазер на данную комнату"}, --  Sulfur
	[557] = {"557", "Печенье с предсказанием", "Даёт одну из следующих наград:#Предсказание#{{SoulHeart}} Синее сердце#{{Rune}} Руну или камень души#{{Card}} Карту Таро#{{Trinket}} Брелок"}, --  Fortune Cookie
	[558] = {"558", "Бельмо", "Шанс выстрелить 1-3 дополнительными слезами в случайных направлениях#{{Luck}} Не зависит от удачи"}, --  Eye Sore
	[559] = {"559", "120 вольт", "Поражает врагов рядом с персонажем электроразрядами#{{Damage}} Электричество наносит до 3.75x урона персонажа в секунду#Разряд может перекинуться ещё на 4 врагов"}, --  120 Volt
	[560] = {"560", "Больно", "{{Timer}} При получении урона до конца комнаты:#↑ {{Tears}} +1.2 к скорострельности при первом ударе#↑ {{Tears}} +0.4 к скорострельности за каждый дополнительный удар#Выпускает кольцо из 10 слёз вокруг персонажа"}, --  It Hurts
	[561] = {"561", "Миндальное молоко", "↑ {{Tears}} x4 множитель скорострельности#↓ {{Damage}} x0.3 множитель урона#↓ {{Tearsize}} -0.16 к размеру слезы#Слёзы получают случайные эффекты брелоков-червей и некоторые эффекты предметов"}, -- Almond Milk
	[562] = {"562", "Каменное дно", "Закрепляет самое высокое значение характеристик персонажа#Фактически они продолжают изменяться как раньше"}, --  Rock Bottom
	[563] = {"563", "Девчачьи бомбы", "+5 бомб#Бомбы взрываются со случайным эффектом бомб"}, --  Nancy Bombs
	[564] = {"564", "Кусок мыла", "↑ {{Tears}} +0.5 к скорострельности#↑ {{Shotspeed}} +0.2 К скорости слезы"}, --  A Bar of Soap
	[565] = {"565", "Кровавый щенок", "Спутник, преследующий врагов#После 15 убийств наносит больше урона, создаёт половину красного сердца каждые 10 убийств и пытается атаковать персонажа#После 40 убийств становится ещё сильнее, создаёт целые красные сердца и может разрушать камни#Получив достаточно урона, возвращается в первую фазу"}, --  Blood Puppy
	[566] = {"566", "Ловец снов", "+1/2 синего сердца при переходе на новый этаж#Отображает предстоящий артефакт Комнаты Сокровищ и Босса при переходе на другой этаж"}, --  Dream Catcher
	[567] = {"567", "Пасхальная свеча", "↑ {{Tears}} +0.4 к скорострельности за каждую зачищенную комнату без получения урона#Накапливается до 5 раз#При получении урона бонус сбрасывается"}, --  Paschal Candle
	[568] = {"568", "Божественное вмешательство", "Двойное нажатие на выстрел, создает щит#Щит существует 1 секунду, отталкивает врагов и отражает вражеские снаряды и лазеры"}, --  Divine Intervention
	[569] = {"569", "Кровавая клятва", "{{Warning}} В начале этажа забирает всё красное здоровье, не убивая персонажа#{{Timer}} До конца этажа:#↑ {{Damage}} +0.0375 × (число потерянных половин сердца)² к урону#↑ {{Speed}} +0.05 × число потерянных половин сердца к скорости#Каждая половина сердца отдельно активирует эффекты получения урона"}, --  Blood Oath
	[570] = {"570", "Пластилиновое печенье", "Каждая слеза будет иметь случайный эффект и цвет"}, --  Playdough Cookie
	[571] = {"571", "Сиротские носки", "Позволяет ходить по шипам и лужам, не получая урон#↑ {{Speed}} +0.3 к скорости#{{SoulHeart}} +2 синих сердца"}, --  Orphan Socks
	[572] = {"572", "Оккультный глаз", "Контролируемые слезы#↑ {{Damage}} +1 к урону#↑ {{Range}} +2 к дальности#↓ {{Shotspeed}} -0.16 к скорости слезы"}, --  Eye of the Occult
	[573] = {"573", "Чистое сердце", "↑ {{Heart}} +1 к здоровью#↑ {{Damage}} x1.2 множитель урона#{{HealingRed}} Полное лечение#20% шанс выстрелить дополнительной орбитальной призрачной слезой"}, --  Immaculate Heart
	[574] = {"574", "Дароносица", "Вокруг персонажа появляется аура, которая наносит урон врагам#Чем ближе к персонажу, тем больше урона"}, --  Monstrance
	[575] = {"575", "Вторженец", "{{Slow}} Зарывается в голову персонажа и выстреливает 4 дополнительными замедляющими слезами, наносящими 1.5 урона#При получении урона имеет 25% шанс выйти из головы и преследовать врагов"}, --  The Intruder
	[576] = {"576", "Грязные мысли", "Все враги-дипы дружелюбны#Разрушение какашек создаёт 1-4 дипа#Тип дипа зависит от типа какашки#Камни имеют 6.25% шанс замениться какашками"}, --  Dirty Mind
	[577] = {"577", "Дамокл", "Над головой персонажа висит меч, который удваивает все предметы на пьедесталах#Не удваивает предметы с ценой или из сундуков#{{Warning}} После получения любого урона меч имеет чрезвычайно низкий шанс мгновенно убить персонажа каждый кадр#Эффекты неуязвимости могут предотвратить смерть"}, --  Damocles
	[578] = {"578", "Бесплатный лимонад", "Создаёт большую лужу жёлтой жижи#Жижа наносит 24 урона в секунду"}, --  Free Lemonade
	[579] = {"579", "Духовный меч", "Вместо слез персонаж размахивает мечом#Наносит 3x + 3.5 урона#Удерживание кнопки атаки заряжает круговую атаку#При полностью заполненных контейнерах может выстрелить слезу"}, --  Spirit Sword
	[580] = {"580", "Красный ключ", "Создает новую комнату, примыкающую к стене, обозначенную контуром двери#Комната может быть особенной#Комната за пределами карты этажа 13х13 телепортирует вас в комнату Я-ОШИБКА"}, --  Red Key
	[581] = {"581", "Пси-муха", "Преследует и блокирует вражеские снаряды#Наносит 15 контактного урона в секунду"}, -- Psy Fly
	[582] = {"582", "Волнистая шляпка", "↑ {{Tears}} +0.75 к скорострельности#↓ {{Speed}} -0.03 к скорости#Искажает экран#При каждом использовании перезаряжается дольше#Выход или зачистка комнат уменьшает эффекты"}, --  Wavy Cap
	[583] = {"583", "Ракета в банке", "+5 бомб#Если персонаж стреляет, то по направлению стрельбы будет запущена ракета#Иначе поставится обычная бомба"}, --  Rocket in a Jar
	[584] = {"584", "Книга добродетелей", "{{AngelChance}} +12.5% к шансу комнаты Ангела, пока предмет в руках#Создаёт орбитального огонька, который стреляет спектральными слезами, но может быть уничтожен#Может совмещаться со вторым активируемым предметом для создания особых огоньков#{{AngelRoom}} Превращает первую комнату Дьявола в комнату Ангела#{{AngelRoom}} Позволяет комнатам Ангела появляться после сделки с Дьяволом"}, -- Book of Virtues
	[585] = {"585", "Алебастровая шкатулка", "Создает 3 синих сердца и 2 Ангельских артефакта#Если была совершена сделка с Дьяволом, то 2 синих сердца и 1 Ангельский артефакт#Заряжается подбирая синие и чёрные сердца"}, --  Alabaster Box
	[586] = {"586", "Лестница", "Создает лестницу, ведущую в комнату Ангела в начале каждого этажа#В ней продаются подбираемые предметы и ангельские артефакты#Исчезает при переходе в другие комнаты"}, --  The Stairway
	[587] = {"587", "", "<Item does not exist>"}, -- Menorah (Unused but skripted)
	[588] = {"588", "Солнце", "{{BossRoom}} Показывает местоположение Комнаты Босса#{{Timer}} После победы над боссом этажа до конца этажа даёт:#↑ {{Damage}} +3 к урону#↑ {{Luck}} +1 к удаче#{{Card20}} Эффект Солнца#{{Battery}} Полностью перезаряжает активный предмет#{{CurseBlind}} Снимает любые проклятия"}, --  Sol
	[589] = {"589", "Луна", "Добавляет дополнительную {{SecretRoom}} Секретную и {{SuperSecretRoom}} Суперсекретную комнату на каждый этаж#Показывает одну Секретную комнату на каждом этаже#{{Timer}} Секретные комнаты содержат луч света, который до конца этажа даёт:#↑ {{Tears}} +0.5 к скорострельности#↑ {{Tears}} Дополнительно +0.5 к скорострельности от первого луча за этаж#{{HalfSoulHeart}} Половину синего сердца"}, --  Luna
	[590] = {"590", "Меркурий", "↑ {{Speed}} +0.4 к скорости#Все обычные двери всегда открыты"}, --  Mercurius
	[591] = {"591", "Венера", "↑ {{Heart}} +1 к здоровью#Лечит 1 красное сердце#Враги около персонажа получают эффект очарования"}, --  Venus
	[592] = {"592", "Земля", "↑ {{Damage}} +1.0 к урону#Заменяет слезы камнями#Они наносят 0.5x-2.0x урона#Могут ломать объекты#Повышает отталкивание"}, --  Terra
	[593] = {"593", "Марс", "При двойном нажатии кнопки передвижения персонаж совершит быстрый рывок#{{Damage}} Во время рывка персонаж неуязвим и наносит 4x урона +8#{{Timer}} Перезарядка: 3 секунды"}, --  Mars
	[594] = {"594", "Юпитер", "↑ {{EmptyHeart}} +2 пустых контейнера сердца#↓ {{Speed}} -0.3 к скорости#{{HealingRed}} Лечит половину сердца#{{Speed}} Скорость увеличивается до +0.5, когда персонаж стоит на месте#{{Poison}} Движение выпускает облака яда#{{Poison}} Иммунитет к яду"}, --  Jupiter
	[595] = {"595", "Сатурн", "При входе в комнату вокруг персонажа начинают вращаться 7 слёз#Эти слёзы существуют 13 секунд и наносят 1.5x урона персонажа +5#Вражеские снаряды имеют шанс начать вращаться вокруг персонажа"}, --  Saturnus
	[596] = {"596", "Уран", "Ледяные слезы, которые замедляют монстров и замораживают их при убийстве#Можно пнуть замерзших врагов, при этом они разлетятся на 10 слёз-сосулек"}, --  Uranus
	[597] = {"597", "Нептун", "{{Tears}} Если не стрелять, бонус слёз накапливается за 3 секунды#Бонус уменьшается во время стрельбы"}, --  Neptunus
	[598] = {"598", "Плутон", "↑ {{Tears}} +0.7 к скорострельности#Значительно уменьшает персонажа, позволяя ему протискиваться между объектами#Выстрелы могут пролететь над персонажем"}, --  Pluto
	[599] = {"599", "Голова вуду", "{{CursedRoom}} Создаёт дополнительную Комнату Проклятий на каждом этаже#Улучшает планировку и награды Комнат Проклятий#{{Coin}} Создаёт монету в каждой Комнате Проклятий"}, --  Voodoo Head
	[600] = {"600", "Глазные капли", "↑ {{Tears}} Уменьшает задержку вылета слезы в левом глазе примерно на 28%"}, --  Eye Drops
	[601] = {"601", "Покаяние", "↑ {{Tears}} +0.7 к скорострельности#+1 вечное сердце#Позволяет Ангельским комнатам появляться даже в том случае, если ранее была заключена сделка с Дьяволом#Получение урона красными сердцами не так сильно снижает шанс сделки"}, --  Act of Contrition
	[602] = {"602", "Членская карточка", "Добавляет люк в каждый магазин, который ведет во второй магазин с предметами по завышенной цене"}, --  Member Card
	[603] = {"603", "Запас батареек", "Создает 2-4 батарейки#Полностью заряжает активируемый предмет"}, --  Battery Pack
	[604] = {"604", "Мамин браслет", "Позволяет подобрать и кинуть объекты#Позволяет переносить их между комнатами"}, --  Mom's Bracelet
	[605] = {"605", "Совок", "↑ {{Damage}} x1.35 множитель урона для правого глаза#{{Timer}} Призывает спутника-подглядывающего на комнату, который оставляет красную жижу и наносит 36 контактного урона в секунду"}, -- The Scooper
	[606] = {"606", "Глазной разлом", "5% шанс выстрелить слезой, создающей разлом при приземлении#{{Luck}} 20% шанс при 15 удачи#Разлом наносит 3x урона персонажа в секунду и притягивает врагов, подбираемые предметы и снаряды"}, --  Ocular Rift
	[607] = {"607", "Малыш нарыв", "Стреляет хаотичными очередями слёз во всех направлениях#Наносит 3.5 или 5.25 урона за слезу"}, --  Boiled Baby
	[608] = {"608", "Замораживающий малыш", "{{Petrify}} Стреляет окаменяющими слезами с 3.5 урона#{{Freezing}} Замораживает врагов после убийства"}, --  Freezer Baby
	[609] = {"609", "Вечный D6", "Изменяет все артефакты на пьедесталах в комнате#25% шанс, что артефакт исчезнет вместо изменения"}, --  Eternal D6
	[610] = {"610", "Птичья клетка", "Прыгает на первого врага, ранившего персонажа в комнате#Наносит 45 урона и выпускает каменную волну#Затем преследует врагов, нанося 6.5 контактного урона в секунду"}, --  Bird Cage
	[611] = {"611", "Глотка", "Персонаж кричит, нанося урон и отталкивая ближайших врагов#Чем больше зарядов, тем сильнее эффект#Также заряжается, получением урона"}, --  Larynx
	[612] = {"612", "Потерянная душа", "Умирает от одного попадания и возрождается в начале следующего этажа#Если довести живым до следующего этажа, создаёт:#{{SoulHeart}} 3 сердца души#{{EternalHeart}} 2 вечных сердца#{{TreasureRoom}} Артефакт Комнаты сокровищ#{{AngelRoom}} Артефакт Комнаты Ангела"}, --  Lost Soul
	[613] = {"613", "", "<Item does not exist>"},
	[614] = {"614", "Кровавые бомбы", "↑ {{Heart}} +1 к здоровью#{{HealingRed}} Лечит 4 красных сердца#Бомбы оставляют красную лужу#{{HalfHeart}} Если бомб нет, можно поставить бомбу ценой в половину сердца"}, --  Blood Bombs
	[615] = {"615", "Малютка Дампи", "Пукающий спутник#Пукает около врагов, с которыми столкнётся, отбрасывая их назад"}, --  Lil Dumpy
	[616] = {"616", "Птичий глаз", "8% шанс выстрелить красным огнём, который блокирует вражеские снаряды и наносит контактный урон#{{Luck}} 50% шанс при 10 удачи#Огонь исчезает после блокирования 4 снарядов, 4 нанесений урона или через 10 секунд"}, --  Bird's Eye
	[617] = {"617", "Магнит", "{{Magnetize}} 17% шанс выстрелить магнитной слезой#{{Luck}} 100% шанс при 5 удачи#Намагниченные враги притягивают подбираемые предметы, снаряды и врагов"}, --  Lodestone
	[618] = {"618", "Тухлый помидор", "{{Bait}} 17% шанс выстрелить слезой, которая помечает врага#{{Luck}} 100% шанс при 5 удачи#Помеченного врага атакуют другие враги"}, --  Rotten Tomato
	[619] = {"619", "Право первородства", "Имеет разный эффект для каждого персонажа"}, --  Birthright
	[620] = {"620", "", "<Item does not exist>"},
	[621] = {"621", "Красная похлёбка", "{{HealingRed}} Полное восстановление здоровья#↑ {{Damage}} +21.6 к урону#Бонус урона уменьшается до нуля 3 минуты#Каждое убийство даёт небольшой бонус к урону, который продлевает действие"}, --  Red Stew
	[622] = {"622", "Генезис", "Удаляет предметы и расходники персонажа и переносит в особую спальню#За каждый удалённый предмет даёт выбор из 3 предметов того же пула#Выход из спальни ведёт на следующий этаж"}, --  Genesis
	[623] = {"623", "Острый ключ", "{{Key}} +5 ключей#Бросает один из ключей персонажа в направлении стрельбы#Брошенные ключи наносят урон, разрушают препятствия и открывают двери#Враги, убитые ключами, могут создать содержимое сундука, включая предметы"}, --  Sharp Key
	[624] = {"624", "Бустер-пак", "Создает 5 случайных карт"}, --  Booster Pack
	[625] = {"625", "Мега-гриб", "Гигантифицирует персонажа и даёт:#↑ {{Damage}} x4 множитель урона#↑ {{Range}} +2 к дальности#↓ {{Tears}} -1.9 к скорострельности#Неуязвимость#Способность сокрушать врагов и препятствия#{{Timer}} Длится 30 секунд и сохраняется между комнатами и этажами"}, -- Mega Mush
	[626] = {"626", "Первая часть ножа", "Превращается в метательный нож, наносящий 25 урона, в сочетании с {{Collectible627}} Частью ножа 2#Нож может открыть дверь из плоти"}, --  Knife Piece 1
	[627] = {"627", "Вторая часть ножа", "Превращается в метательный нож, наносящий 25 урона, в сочетании с {{Collectible626}} Частью ножа 1#Нож может открыть дверь из плоти"}, --  Knife Piece 2
	[628] = {"628", "Свидетельство о смерти", "Перенесет вас на этаж, содержащий все артефакты в игре#После подбора одного артефакта персонаж возвращается"}, --  Death Certificate
	[629] = {"629", "Бот-муха", "Стреляет защищёнными слезами, чтобы уничтожать вражеские снаряды#Наносит 3 контактного урона в секунду"}, -- Bot Fly
	[630] = {"630", "", "<Item does not exist>"},
	[631] = {"631", "Мясной тесак", "Разделяет всех врагов в комнате на 2 меньшие версии с 40% здоровья#Враги, которые естественно разделяются, получают достаточно урона, чтобы разделиться#Наносит 25 урона врагам, которых нельзя разделить"}, --  Meat Cleaver
	[632] = {"632", "Злой амулет", "↑ {{Luck}} +2 к удаче#Иммунитет к эффектам горения, ошеломления, страха, отравления и облаков ядовитого газа"}, --  Evil Charm
	[633] = {"633", "Догма", "↑ {{Speed}} +0.1 к скорости#↑ {{Damage}} +2 к урону#Полёт и одноразовый щит {{HolyMantleSmall}} Святой мантии#{{Heart}} Лечит красными и синими сердцами, если у персонажа меньше 6 сердец"}, --  Dogma
	[634] = {"634", "Чистилище", "Находясь в комнате с врагами, создает трещины на земле#Хождение по этим трещинам вызывает взрывающихся призраков"}, --  Purgatory
	[635] = {"635", "Шов", "Спутник, который движется в направлении выстрелов персонажа#При использовании, персонаж меняется местами со спутником и получает кратковременную неуязвимость#Телепортация на объекты и врагов может повредить или уничтожить их"}, --  Stitches
	[636] = {"636", "Клавиша R", "Создаёт новый забег с сохранением собранных артефактов и предметов, и перемещает вас на первый этаж#Также сохраняет время"}, --  R Key
	[637] = {"637", "Нокаутные капли", "{{Confusion}} 10% шанс выстрелить кулаком, который вызывает замешательство и сильное отбрасывание#{{Luck}} 100% шанс при 9 удачи#Враги получают урон, когда их отбрасывает в стену или препятствие"}, --  Knockout Drops
	[638] = {"638", "Ластик", "Бросает ластик, который мгновенно убивает обычного врага#Предотвращает появление стёртого врага на протяжении всего забега#Боссам наносит 15 урона#Можно использовать 1 раз на каждом этаже"}, --  Eraser
	[639] = {"639", "Фу-сердце", "Дает Гнилое Сердце при использовании"}, --  Yuck Heart
	[640] = {"640", "Урна душ", "Активация открывает и закрывает урну#Испускает поток пламени#Получает заряды каждый раз, когда враг умирает"}, --  Urn of Souls
	[641] = {"641", "Акелдама", "Создает цепочку слез позади вас во время боя#Слезы наносят 3.5 урона"}, --  Akeldama
	[642] = {"642", "Магическая кожа", "Создает артефакт из пула текущей комнаты#{{BrokenHeart}} Превращает 1 контейнер красного сердца, 1 костяное сердце или 2 синих сердца в сломанное сердце#{{Warning}} Может заменять будущие артефакты, если предмет не удерживается (33% после 1 использования, 50% после 2, 100% после 3)#Шанс ниже, если Магическая кожа лежит на пьедестале текущего этажа"}, --  Magic Skin
	[643] = {"643", "Откровение", "{{SoulHeart}} +2 синих сердца#Полёт#{{Chargeable}} Заряжаемый святой луч с высоким уроном#Не заменяет обычные слёзы"}, --  Revelation
	[644] = {"644", "Утешительный приз", "Повышает самую низкую характеристику#Даёт 3 монеты, 1 бомбу, или 1 ключ в зависимости от того, чего у вас меньше всего"}, --  Consolation Prize
	[645] = {"645", "Крошечная тома", "Большой орбитальный спутник, который блокирует выстрелы#Наносит 3.5 контактного урона в секунду#Разделяется на меньшие версии после получения 3 ударов#Меньшие версии разлетаются на синих пауков#Возрождается через 5 секунд после полного исчезновения"}, -- Tinytoma
	[646] = {"646", "Серные бомбы", "{{Bomb}} +5 бомб#{{Collectible118}} Бомбы выпускают 4-сторонний кровавый луч#Лучи не вредят персонажу"}, --  Brimstone Bombs
	[647] = {"647", "4.5 вольт", "Зачистка комнат больше не заряжает активные предметы#Нанесение урона врагам медленно заполняет полосу заряда#Урон, необходимый для одного заряда, увеличивается на каждом этаже"}, --  4.5 Volt
	[648] = {"648", "", "<Item does not exist>"},
	[649] = {"649", "Фруктовая слива", "Движется по диагонали по комнате, стреляя слезами на своём пути, которые наносят 3 урона#Наносит 6 контактного урона в секунду"}, -- Fruity Plum
	[650] = {"650", "Сливовая флейта", "Призывает спутника Сливовую малышку в текущую комнату на 10 секунд"}, --  Plum Flute
	[651] = {"651", "Вифлеемская звезда", "Спутник медленно движется от стартовой комнаты к {{BossRoom}} Комнате Босса#Внутри ауры:#↑ {{Tears}} x2.5 множитель скорострельности#↑ {{Damage}} x1.8 множитель урона#Самонаводящиеся слёзы#50% шанс избежать урона"}, --  Star of Bethlehem
	[652] = {"652", "Малыш в кубе", "Его можно пинать касанием#{{Slow}} Замедляет и наносит до 17.5 контактного урона в зависимости от скорости#{{Freezing}} Замораживает убитых врагов"}, --  Cube Baby
	[653] = {"653", "Возвратися воспять", "При удержании непризрачные враги после смерти создают маленьких красных призраков#Использование взрывает призраков#Также убивает любых врагов-призраков, включая боссов, если у них меньше 50% здоровья"}, --  Vade Retro
	[654] = {"654", "Ложный диплом", "{{BlackHeart}} +1 чёрное сердце#{{Pill}} Идентифицирует все пилюли#Превращает все хорошие пилюли в плохие#↑ {{Damage}} Пилюля, понижающая характеристику, даёт +0.6 к урону#{{BlackHeart}} Другие плохие пилюли создают чёрное сердце"}, -- False PHD
	[655] = {"655", "Крути, чтоб выиграть", "Даёт орбиталь, которая блокирует вражеские снаряды и наносит 10.5 контактного урона в секунду#При использовании:#↑ {{Speed}} +0.5 к скорости#Повышает скорость и урон орбиталей"}, --  Spin to Win
	[656] = {"656", "Дамоклов меч", "Над головой персонажа висит меч, который удваивает все предметы на пьедесталах#Не удваивает предметы с ценой или из сундуков#{{Warning}} После получения любого урона меч имеет чрезвычайно низкий шанс мгновенно убить персонажа каждый кадр#Эффекты неуязвимости могут предотвратить смерть"}, -- Damocles (hidden passive version)
	[657] = {"657", "Васкулит", "После убийства врага из него вылетают слёзы, летящие в случайном направлении"}, --  Vasculitis
	[658] = {"658", "Огромная клетка", "Создает микро-персонажей при получении урона#Они преследуют и стреляют в ближайших врагов"}, --  Giant Cell
	[659] = {"659", "Тропикамид", "↑ {{Range}} +2.5 дальности#↑ {{Tearsize}} +0.22 к размеру слезы"}, --  Tropicamide
	[660] = {"660", "Гадание на картах", "В стартовой комнате каждого этажа создаёт 2 портала; они исчезают при выходе#{{ColorRed}}Красный:{{CR}} {{BossRoom}} Комната Босса#{{ColorYellow}}Жёлтый:{{CR}} {{TreasureRoom}} Комната Сокровищ#{{ColorBlue}}Синий:{{CR}} {{SecretRoom}} Секретная комната" }, --  Card Reading
	[661] = {"661", "Пятерняшки", "Убийство врага призывает стационарного спутника на его месте#Максимум может создать 5 спутников"}, --  Quints
	[662] = {"662", "", "<Item does not exist>"}, -- Pacifist (Cut item)
	[663] = {"663", "Зуб и гвоздь", "1 секунда неуязвимости каждые 6 секунд#Персонаж мигает прямо перед срабатыванием эффекта"}, --  Tooth and Nail
	[664] = {"664", "Кутёжник", "↑ {{Heart}} +1 к здоровью#{{HealingRed}} Полное лечение#Пьедесталы переключаются между артефактом и едой#Поднятие еды даёт:#{{HealingRed}} Лечение 2 сердец#↑ {{Damage}} Временно +3.6 к урону#↑ 2 постоянных повышения характеристик, зависящих от еды#↓ {{Speed}} -0.03 к скорости"}, --  Binge Eater
	[665] = {"665", "Глаз Гаппи", "Показывает содержимое костров, мешочков, сундуков и лавочников до их открытия"}, --  Guppy's Eye
	[666] = {"666", "", "<Item does not exist>"}, -- HELL!!
	[667] = {"667", "Соломенное чучело", "{{Bomb}} +1 Бомба#Создает Хранителя как второго персонажа#Когда он умирает, появляются синие пауки, предмет удаляется и предметы которые Хранитель подобрал удаляются тоже#Сделки с дьяволом стоят монеты, пока Хранитель жив# !!! Может подбирать сюжетные предметы" }, --  Strawman
	[668] = {"668", "Папина записка", "После подбора начинается восхождение"}, --  Dad's Note
	[669] = {"669", "Сосиска", "↑ {{Heart}} +1 к здоровью#↑ {{Speed}} +0.2 скорости#↑ {{Damage}} +0.5 урона#↑ {{Tears}} +0.5 скорострельности#↑ {{Range}} +2.5 дальности#↑ {{Shotspeed}} +0.16 скорости слезы#↑ {{Luck}} +1 удачи#{{HealingRed}} Полное лечение#↑ {{AngelDevilChance}} +6.9% к шансу Комнаты Дьявола/Ангела#↑ {{PlanetariumChance}} +6.9% к шансу Планетария"}, --  Sausage
	[670] = {"670", "Выбор?", "Если после зачистки комнаты дается награда, то на выбор будет две разные награды#Поднятие одного приводит к исчезновению другого"}, --  Options?
	[671] = {"671", "Конфетное сердце", "За каждую исцелённую половину красного сердца с помощью подбираемых сердец навсегда увеличивает случайную характеристику"}, --  Candy Heart
	[672] = {"672", "Фунт плоти", "Сделки с Дьяволом теперь требуют монеты#Предметы в магазине теперь требуют сердца#Расходные материалы в магазинах бесплатны, но окружены шипами"}, --  A Pound of Flesh
	[673] = {"673", "Искупление", "{{DevilRoom}} При входе на новый этаж после посещения Комнаты Дьявола без взятия предмета или подбираемого предмета даёт:#↑ {{Damage}} +1 к урону#{{SoulHeart}} +1 синее сердце"}, --  Redemption
	[674] = {"674", "Духовные цепи", "После смерти призрак персонажа прикован к его мертвому телу, и он может продолжать сражаться с половиной сердца#Возвращение к жизни через 10 секунд#Заряжается при поднятии синего сердца"}, --  Spirit Shackles
	[675] = {"675", "Треснувший шар", "При получении урона открывает все двери и проходы, уничтожает скрытые камни и камни с ретро сокровищницами в комнате#Раскрывается случайная комната#Может открыть сюжетные двери#Может раскрыть {{UltraSecretRoom}} Ультра секретную комнату"}, --  Cracked Orb
	[676] = {"676", "Пустое сердце", "Если у персонажа есть одно или менее красных сердец, то в начале следующего этажа даётся пустой контейнер здоровья#Костяные сердца не в счет"}, --  Empty Heart
	[677] = {"677", "Астральная проекция", "{{Timer}} При получении урона в незачищенной комнате до конца боя:#Спектральные слёзы#Полёт#Блокирует следующий урон#Останавливает время на 2 секунды#На 2 секунды значительно повышает скорость и скорострельность"}, --  Astral Projection
	[678] = {"678", "Кесарево", "Заменяет слёзы на заряжаемую атаку спектральными самонаводящимися зародышами#Зародыши наносят 2.8x от базового урона в секунду" }, --  C Section
	[679] = {"679", "Малютка Абаддон", "{{Collectible399}} Спутник, который заряжается и выпускает круг Пасти бездны#Он наносит 52.5 урона за 1 секунду"}, --  Lil Abaddon
	[680] = {"680", "Месть Монтесумы", "{{Chargeable}} Непрерывная стрельба заряжает короткий мощный луч назад#Не заменяет обычные слёзы"}, --  Montezuma's Revenge
	[681] = {"681", "Малютка портал", "Спутник, который летит по направлению стрельбы, наносит урон врагам и собирает подбираемые предметы на своём пути#Создаёт синюю муху за каждый#За каждые 4 предмета создаёт портал в неисследованную комнату"}, --  Lil Portal
	[682] = {"682", "Червячок-друг", "Иногда вырывается из-под земли и хватает врага#Схваченные враги получают 8 урона в секунду, замедляются и не могут двигаться"}, --  Worm Friend
	[683] = {"683", "Костяные шпоры", "Убитые враги оставляют после себя осколки летающих костей#Они блокируют выстрелы и наносят контактный урон"}, --  Bone Spurs
	[684] = {"684", "Голодная душа", "Убийство врага имеет 33% шанс создать призрака#Призраки преследуют врагов, наносят контактный урон и взрываются через 5 секунд#Персонаж не получает урона от взрыва"}, --  Hungry Soul
	[685] = {"685", "Банка огоньков", "При использовании создаёт огонёк, подобный от {{Collectible584}} Книги добродетелей#Сначала создаёт только один огонёк, но после каждого использования создаёт на один больше#Максимум до 12"}, --  Jar of Wisps
	[686] = {"686", "Медальон души", "За каждую поднятую половину синего или чёрного сердца навсегда увеличивается случайная характеристика#Создает синее сердце"}, --  Soul Locket
	[687] = {"687", "Поиск друзей", "Создает случайного дружелюбного монстра, который имитирует движения и атаки персонажа"}, --  Friend Finder
	[688] = {"688", "Внутренний ребёнок", "+1 Дополнительная жизнь#Перерождение в текущей комнате с половиной сердца, очень маленьким размером и +0.2 к скорости"}, --  Inner Child
	[689] = {"689", "Глючная корона", "Пьедесталы предметов быстро переключаются между 5 случайными предметами"}, --  Glitched Crown
	[690] = {"690", "Жевательное драже", "Заставляет врагов отскакивать от персонажа при прикосновении#Отскакивание их в препятствия наносит им урон#50% шанс отразить выстрелы#50% шанс игнорировать контактный урон"}, --  Belly Jelly
	[691] = {"691", "Священный шар", "Предотвращает появление артефактов качества {{Quality0}}/{{Quality1}}#Артефакты качества {{Quality2}} имеют 33% шанс быть изменёнными"}, --  Sacred Orb
	[692] = {"692", "Кровавые узы", "Создает специальные шипы в Дьявольской комнате#Получение урона от шипов может дать награду:#35%: ничего#33%: +0.5 к урону#15%: 6 монет#10%: 2 чёрных сердца#5%: случайный дьявольский артефакт#2%: Трансформация Левиафан"}, --  Sanguine Bond
	[693] = {"693", "Рой", "Создает 8 орбитальных мух, которые превращаются в синих мух после блокирования выстрела#Создает новую муху после зачистки комнаты"}, --  The Swarm
	[694] = {"694", "Горе", "Дает 3 сломанных сердца#↑ {{Damage}} +0.25 к урону за каждое сломанное сердце#Каждый смертельный удар добавит еще 2 разбитых сердца#Умираете, при достижении 12 сломанных сердец"}, --  Heartbreak
	[695] = {"695", "Кровавый порыв", "При получении урона повышает скорость и скорострельность до конца этажа#Максимум: +1.02 к скорости и +3 к скорострельности"}, --  Bloody Gust
	[696] = {"696", "Спасение", "Вокруг персонажа появляется аура, при нахождении врага в которой над ним появляется столб света#Аура увеличивается, от количества полученного урона на этаже"}, --  Salvation
	[697] = {"697", "Исчезающий близнец", "Спутник, который становится клоном босса при входе в комнату босса#Победа над ним создает дополнительный артефакт#Клон медленнее и имеет 75% от исходного здоровья босса"}, --  Vanishing Twin
	[698] = {"698", "Нечестивая парочка", "Два спутника, стоящие по бокам#Слёзы равны вашим, но только с 37.5% вашего урона"}, --  Twisted Pair
	[699] = {"699", "Ярость Азазеля", "Персонаж получает ярость, после каждой зачищенной комнаты#Через 4 комнаты он стреляет большим потоком Серы при входе в следующую комнату"}, --  Azazel's Rage
	[700] = {"700", "Эхо-камера", "Когда персонаж использует карту, пилюлю или руну, он также использует копии 3 последних карт/пилюль/рун, которые использовались с момента получения Эхо-камеры"}, --  Echo Chamber
	[701] = {"701", "Гробница Исаака", "Создает старый сундук в начале каждого этажа#Может содержать:#1-3 синих сердца#3 брелока#Артефакт мамы или папы#Артефакт ангела"}, --  Isaac's Tomb
	[702] = {"702", "Мстительный дух", "После получения урона создает спутника-огонька до конца этажа#Максимум 6 спутников#Они стреляют огненными слезами, но не блокируют выстрелы"}, --  Vengeful Spirit
	[703] = {"703", "Исав Младший", "При использовании происходит переключение между текущим персонажем и Исавом-младшим, который имеет 3 чёрных сердца, +2 к урону и полет#Персонажи имеют независимые предметы и здоровье#!!! При его смерти, забег заканчивается"}, --  Esau Jr.
	[704] = {"704", "Берсерк!", "{{Battery}} Заряжается нанесённым уроном#{{Timer}} На 5 секунд:#↑ {{Speed}} +0.4 скорости#↓ {{Tears}} x0.5 множитель скорострельности#↑ {{Tears}} +2 скорострельности#↑ {{Damage}} +3 урона#Ближняя атака отражает снаряды#{{Timer}} Каждое убийство продлевает эффект на 1 секунду и ненадолго даёт неуязвимость"}, --  Berserk!
	[705] = {"705", "Тёмные искусства", "{{Timer}} На 1 секунду или до начала стрельбы:#↑ {{Speed}} +1 скорости#Позволяет проходить сквозь врагов и снаряды, парализуя их#После окончания эффекта парализованным врагам наносится урон, снаряды уничтожаются, а на месте персонажа происходит взрыв#Сила атак растёт с числом затронутых врагов и снарядов"}, --  Dark Arts
	[706] = {"706", "Бездна", "Поглощает все пьедесталы с предметами в комнате и создаёт саранчу-спутника за каждый из них#Саранча наносит урон персонажа 2-3 раза за атаку#Некоторые предметы создают особую саранчу при поглощении"}, --  Abyss
	[707] = {"707", "Ужин", "↑ {{Heart}} +1 к здоровью#Лечит 1 красное сердце"}, --  Supper
	[708] = {"708", "Степлер", "↑ {{Damage}} +1.0 к урону#Персонаж стреляет слезами из одного глаза"}, --  Stapler
	[709] = {"709", "Суплекс!", "Рывок в направлении движения#При столкновении хватает врага и бросает его, нанося 50 урона и создавая каменные волны#Размер персонажа влияет на урон и радиус#Неуязвимость во время рывка и броска"}, --  Suplex!
	[710] = {"710", "Мешок создания", "Имеет 8 слотов для подбираемых предметов#Когда все 8 заполнены, появляется возможность создать из них артефакт на пьедестале#Редкость артефакта зависит от редкости предметов"}, --  Bag of Crafting
	[711] = {"711", "Кувырок", "У артефакта, сгенерированного при входе в комнату, позади появляется второй артефакт с помехами#При активировании артефакты меняются местами#Если остался только артефакт с помехами, то при выходе из комнаты он исчезнет, но при активации он станет обычным"}, --  Flip
	[712] = {"712", "Лемегетон", "При использовании создает разрушаемый огонёк с эффектом пассивного артефакта#Этот эффект применяется к персонажу#Артефакт создаётся из пула данной комнаты c шансом 25%, иначе из случайного пула"}, --  Lemegeton
	[713] = {"713", "Свищ", "При использовании превращает половину сердца в разрушаемых спутников#Их нельзя превратить обратно в сердца#Виды сердец влияют на создаваемых спутников"}, --  Sumptorium
	[714] = {"714", "Отзыв", "Возвращает тело Забытого с любого расстояния"}, --  Recall
	[715] = {"715", "Баночка", "Сохраняет внутри одну какашечную бомбу, которую можно использовать позже"}, --  Hold
	[716] = {"716", "Мешок Хранителя", "Создает 3 {{Coin}} монеты и 1 {{Key}} ключ#{{Shop}} За каждые потраченные 3 монеты даёт одно из:#↑ {{Speed}} +0.03 скорости#↑ {{Damage}} +0.5 урона#↑ {{Range}} +0.25 дальности"}, --  Keeper's Sack
	[717] = {"717", "Родня Хранителя", "В комнате с врагами камни и вазы могут создать синих пауков#При уничтожении они создают 2 синих паука"}, --  Keeper's Kin
	[718] = {"718", "", "<Item does not exist>"}, -- Keepers Robe (Cut item)
	[719] = {"719", "Коробок Хранителя", "На полу появляется случайный расходник или артефакт на продажу"}, --  Keeper's Box
