	[721] = {"721", "ТМТРЕЙНЕР", "Все будущие артефакты становятся глючными#Глючные артефакты имеют полностью случайные эффекты"}, --  TMTRAINER
	[722] = {"722", "Анима сола", "Приковывает ближайшего врага цепями на 5 секунд, не давая ему двигаться"}, --  Anima Sola
	[723] = {"723", "Кубик с вычетом", "Изменяет все артефакты в комнате на другие, вычитая единицу из ID каждого"}, --  Spindown Dice
	[724] = {"724", "Гиперкоагуляция", "При получении урона от врага, на пол падает половина или полное красное сердце#Сердца пропадают через 1.5 секунды"}, --  Hypercoagulation
	[725] = {"725", "СРК", "После нанесения достаточного урона персонаж начинает краснеть#При отпускании кнопки стрельбы во время мигания происходит одно из:#Бросок случайной какашки#Создание усиливающей лужи#{{Poison}} Отравляющий пук#Создание 5 активных бомб"}, --  IBS
	[726] = {"726", "Кровохарканье", "Двойное нажатие кнопки стрельбы заставляет персонажа чихнуть кровью#Чих наносит 1.5x урона персонажа#Перезарядка 1 секунду#{{BrimstoneCurse}} Поражённые враги получают дополнительный урон от лучей Серы"}, --  Hemoptysis
	[727] = {"727", "Призрачные бомбы", "{{Bomb}} +5 бомб#Бомбы создают призраков, которые преследуют врагов, наносят 2x урона персонажа в секунду и взрываются через 10 секунд"}, --  Ghost Bombs
	[728] = {"728", "Гелло", "До конца комнаты из персонажа появляется демон-спутник#Он стреляет в ближайшего врага, копируя слёзы, характеристики и эффекты персонажа#{{Damage}} Его слёзы наносят 75% урона персонажа"}, --  Gello
	[729] = {"729", "Голову с плеч", "Бросает голову персонажа в выбранном направлении#Голова наносит контактный урон и стреляет слезами с места приземления#Повторное использование предмета или наступление на голову возвращает её на место"}, --  Decap Attack
	[730] = {"730", "Стеклянный Глаз", "↑ {{Damage}} +0.75 к урону#↑ {{Luck}} +1 к удаче"}, --  Glass Eye
	[731] = {"731", "Ячмень", "!!! Только для правого глаза:#↑ {{Damage}} x1.28 множитель урона#↑ {{Range}} +6.5 дальности#↓ {{Shotspeed}} -0.3 скорости слезы"}, --  Stye
	[732] = {"732", "Мамино Кольцо", "↑ {{Damage}} +1 к урону#Создаёт руну или камень души на полу"}, --  Mom's Ring
}
