	[172] = {"172", "Проклятый пенни", "Телепортирует в случайную комнату при подборе монеты#Может телепортировать в секретные комнаты"}, --  Cursed Penny
	[173] = {"173", "Твоя душа", "{{DevilRoom}} Позволяет бесплатно взять 1 артефакт в Комнате Дьявола#{{Warning}} Бесплатная сделка всё равно влияет на шанс Комнаты Ангела"}, --  Your Soul
