	[175] = {"175", "Странный ключ", "Открывает проход в Синюю Матку, независимо от времени#Использование {{Collectible297}} Ящика Пандоры создает 6 случайных предметов из случайных пулов, при этом артефакт и брелок исчезнут"}, --  Strange Key
	[176] = {"176", "Малыш сгусток", "Создаёт кровяной сгусток, повторяющий движения персонажа#Копирует характеристики, эффекты слёз и 35% урона персонажа#Возрождается в каждой комнате"}, --  Lil Clot
	[177] = {"177", "Временная татуировка", "После прохождения {{ChallengeRoom}} Комнаты Испытаний создаёт случайный сундук#После прохождения {{BossRushRoom}} Комнаты Испытаний Боссами создаёт артефакт"}, --  Temporary Tattoo
	[178] = {"178", "Проглоченный М80", "При получении урона персонаж с шансом 50% взрывается#Не уничтожает автоматы сдачи крови и исповедальни, но создаёт подбираемые предметы, как при их уничтожении"}, --  Swallowed M80
	[179] = {"179", "Пульт радиоуправления", "Спутники копируют движения персонажа#Удерживайте {{ButtonRT}}, чтобы оставить их на месте"}, --  RC Remote
	[180] = {"180", "Найденная душа", "Повторяет движения персонажа и стреляет спектральными слезами#Копирует характеристики, эффекты слёз и 50% урона персонажа#Использует большинство активных предметов вместе с персонажем#Умирает от одного попадания#Возрождается на каждом этаже"}, --  Found Soul
	[181] = {"181", "Пакет расширения", "Использование активируемого артефакта вызывает эффект дополнительного активируемого артефакта с 1-2 зарядами"}, --  Expansion Pack
	[182] = {"182", "Сущность Вифы", "При входе в {{AngelRoom}} Комнату Ангела создаёт 5 огоньков#Пожертвование попрошайкам с шансом 25% создаёт огонёк"}, --  Beth's Essence
	[183] = {"183", "Близнецы", "50% шанс удвоить спутника в каждой комнате#Если у персонажа нет спутников, даёт {{Collectible8}} Братика Бобби или {{Collectible67}} Сестру Мэгги"}, --  The Twins
	[184] = {"184", "Документы об усыновлении", "В магазинах теперь продаются Спутники#Спутники всегда будут за 10 монет"}, --  Adoption Papers
