	[21] = {"Порченый Исаак", "Пьедесталы циклически меняются между 2 предметами#Можно нести только 8 пассивных предметов#Выбор предмета, который будет сброшен ради 9-го, меняется кнопкой {{ButtonRT}}"},
	[22] = {"Порченая Магдалина", "Здоровье выше 2 красных сердец постепенно истощается#При контакте наносит удар ближнего боя с 6x уроном#{{HalfHeart}} Враги могут оставить половину красного сердца на 2 секунды#При убийстве в ближнем бою сердце выпадает всегда#{{Collectible45}} Лечится вдвое сильнее от источников, кроме подбираемых предметов#{{AngelDevilChance}} Урон истощаемым сердцам не влияет на шанс сделки"},
