	[25] = {"Порченый ???", "Бомбы заменены заклинаниями какашек#{{Crafting29}} Нанесение урона создаёт подбираемые какашки#{{Collectible715}} Следующее заклинание можно сохранить на потом с помощью Удержания"},
	[26] = {"Порченая Ева", "Удержание огня превращает сердца в спутников-сгустков#Разные типы сердец создают сгустки с большим здоровьем и эффектами слёз#Сгустки постепенно теряют здоровье#Удержание {{ButtonRT}} оставляет сгустки на месте#При половине сердца без сгустков даёт атаку, похожую на Мамин нож, до лечения и выхода из комнаты"},
	[27] = {"Порченый Самсон", "Нанесение и получение урона накапливает режим Берсерка#{{Timer}} В режиме Берсерка на 5 секунд:#↑ {{Speed}} +0.4 к скорости#↓ {{Tears}} x0.5 множитель скорострельности#↑ {{Tears}} +2 к скорострельности#↑ {{Damage}} +3 к урону#Атака заменяется отражающим выстрелы ближним боем#{{Timer}} Каждое убийство продлевает эффект на 1 секунду и ненадолго даёт неуязвимость"},
	[28] = {"Порченый Азазель", "В начале зарядки чихает кровью#Попадание чихом вдвое сокращает время зарядки#Чих наносит 1.5x урона Азазеля#{{BrimstoneCurse}} Поражённые враги получают дополнительный урон от лучей Серы#При смерти проклятые враги взрываются и передают проклятие ближайшим врагам"},
	[29] = {"Порченый Лазарь", "У Лазаря два состояния со своими предметами и здоровьем#Зачистка комнаты/волны или использование Переворота переключает состояние"},
	[30] = {"Порченый Эдем", "При получении урона меняет характеристики, предметы, брелок и расходники#Предметы меняются на предметы из того же пула#Самоурон ничего не меняет"},
	[31] = {"Порченый Потерянный", "{{Card51}} Появившиеся карты имеют 10% шанс стать Святой картой#Предметы качества {{Quality2}} или ниже имеют 20% шанс измениться#Появляются только наступательные предметы"},
	[32] = {"Порченая Лилит", "Нажатие огня выпускает плод в ближнюю атаку с 3x уроном#Удержание огня оставляет плод снаружи стрелять по ближайшему врагу"},
	[33] = {"Порченый Хранитель", "Максимум 2 монетных сердца#Враги оставляют монеты, исчезающие через 2 секунды#Большинство пьедесталов стоит 15 монет#Дьявольские сделки и предметы Ангела стоят 15 или 30 монет#Магазины не требуют ключа и содержат больше товаров"},
	[34] = {"Порченый Аполлион", ""},
	[35] = {"Порченый Забытый", "Забытый - неподвижная куча костей, которую Душа подбирает и бросает с 3x уроном#Урон получает только Душа#Бомбы ставятся на месте Забытого#Не может иметь красных сердец#{{SoulHeart}} Увеличение здоровья даёт синие сердца"},
	[36] = {"Порченая Вифания", "{{Heart}} Использует красные сердца для зарядки активного предмета#Не может иметь красных сердец#{{SoulHeart}} Увеличение здоровья даёт синие сердца и кровавые заряды#Повышение характеристик эффективно только на 75%"},
	[37] = {"Порченый Иаков", "Тёмный Исав преследует персонажа и совершает рывок вблизи#Рывок наносит врагам большой урон#При попадании превращает персонажа в призрака, умирающего от одного удара до конца этажа#Призрак может бесплатно взять одну дьявольскую сделку за комнату"},
	[38] = {"Мёртвый Порченый Лазарь", "У Лазаря два состояния со своими предметами и здоровьем#Зачистка комнаты/волны или использование Переворота переключает состояние"},
	[39] = {"Душа Порченого Иакова", "Полёт#Спектральные слёзы#{{Warning}} Нет здоровья#{{Warning}} Умирает от попадания Тёмного Исава#{{DevilRoom}} Можно бесплатно взять одну дьявольскую сделку за комнату#На следующем этаже снова становится Порченым Иаковом"},
	[40] = {"Душа Порченого Забытого", "Забытый - неподвижная куча костей, которую Душа подбирает и бросает с 3x уроном#Урон получает только Душа#Бомбы ставятся на месте Забытого#Не может иметь красных сердец#{{SoulHeart}} Увеличение здоровья даёт синие сердца"},
